from django.db.models import Sum


def split_existing_raised(apps, schema_editor):
    """Until now `raised` was typed in by hand. Keep those numbers as prior,
    off-platform funding so totals don't change; platform investments that
    were already accepted stay counted on top."""
    Startup = apps.get_model('startups', 'Startup')
    Investment = apps.get_model('startups', 'Investment')
    for startup in Startup.objects.all():
        platform = Investment.objects.filter(
            startup=startup, status__in=('accepted', 'completed'),
        ).aggregate(t=Sum('amount'))['t'] or 0
        startup.external_raised = max(startup.raised - platform, 0)
        startup.raised = startup.external_raised + platform
        startup.save(update_fields=['external_raised', 'raised'])


